    GPIOA->MODER &= (0b11 << GPIO_MODER_MODER5_Pos); // Clear mode bits for pin 5
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODER5_Pos); // Set pin 5 as output
    
    GPIOA->MODER &= (0b11 << GPIO_MODER_MODER8_Pos); // Clear mode bits for pin 5
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODER8_Pos); // Set pin 5 as output

    GPIOA->MODER &= (0b11 << GPIO_MODER_MODER9_Pos); // Clear mode bits for pin 5
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODER9_Pos); // Set pin 5 as output

    GPIOA->MODER &= (0b11 << GPIO_MODER_MODER6_Pos); // Clear mode bits for pin 5
    GPIOA->MODER |= (0b01 << GPIO_MODER_MODER6_Pos); // Set pin 5 as output

    GPIOA->OTYPER &= ~(0b1 << GPIO_OTYPER_OT5_Pos); // Set pin 5 as push-pull
    GPIOA->OTYPER &= ~(0b1 << GPIO_OTYPER_OT8_Pos); // Set pin 8 as push-pull
    GPIOA->OTYPER &= ~(0b1 << GPIO_OTYPER_OT9_Pos); // Set pin 9 as push-pull
    GPIOA->OTYPER &= ~(0b1 << GPIO_OTYPER_OT6_Pos); // Set pin 6 as push-pull

    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED5_Pos); // Clear speed bits for pin 5
    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED8_Pos); // Clear speed bits for pin 5
    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED9_Pos); // Clear speed bits for pin 5
    GPIOA->OSPEEDR &= ~(0b11 << GPIO_OSPEEDR_OSPEED6_Pos); // Clear speed bits for pin 5


    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD5_Pos); // No pull-up, no pull-down
    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD8_Pos); // No pull-up, no pull-down
    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD9_Pos); // No pull-up, no pull-down
    GPIOA->PUPDR &= ~(0b11 << GPIO_PUPDR_PUPD6_Pos); // No pull-up, no pull-down

    GPIOA->ODR |= (0b1 << GPIO_ODR_OD5_Pos); // Set pin 5 high
